// Señales por código, antes de cualquier IA: identidad, inyección y pedidos sobre datos personales.
const r = $input.first().json;
const t = String(r.texto || '');
const id = (r.prefijo_id || '') + r.reclamo_id;
const dni = (t.match(/DNI:?\s*(\d{1,2}\.?\d{3}\.?\d{3})/i) || t.match(/\b(\d{7,8})\b/) || [])[1] || '';
const tel = (t.match(/\b(\d{2,4}-\d{4}-\d{4})\b/) || [])[1] || '';
const FRASES = [
  /ignor[aá]\w*\s+(las|tus|todas\s+las)?\s*(instrucciones|reglas)/i,
  /instrucci[oó]n(es)?\s+para\s+el\s+sistema/i,
  /system\s+prompt|ignore\s+(all|previous)/i,
  /marc[aá]\w*\s+(este|el)\s+reclamo\s+como/i,
  /(envi[aá]\w*|pas[aá]\w*|mand[aá]\w*)\s+(me\s+)?la\s+lista\s+de\s+clientes/i,
];
const inyeccion = FRASES.map((f) => (t.match(f) || [])[0]).filter(Boolean);
const PEDIDO_DATOS = /(borr|elimin|supr)\w*\s+(todos\s+)?(mis\s+|los\s+)?datos|acceso\s+a\s+(mis\s+)?datos|rectific\w*\s+(mis\s+)?datos|qu[eé]\s+datos\s+(m[ií]os\s+)?(tienen|guardan)/i;
return [{ json: { reclamo_id: id, canal: r.canal, sucursal: r.sucursal, fecha_hora_ingreso: r.fecha_hora_ingreso, texto: t,
  dni, telefono: tel, sospechoso: inyeccion.length > 0, motivo_seguridad: inyeccion.length ? 'Frase típica de inyección: "' + inyeccion.join('", "') + '"' : null,
  pedido_datos_personales: PEDIDO_DATOS.test(t) } }];

const r = $('CA85a_Preparar').first().json;
const c = $input.first().json;
return [{ json: { modo: 'texto', texto: r.texto, cliente_id: c.cliente_id || null, documento_id: r.reclamo_id, origen: 'reclamos' } }];

// La IA solo elige de listas cerradas. Cualquier otra respuesta se descarta (salida validada por código).
const CATS = ["Entrega demorada", "Material dañado", "Faltante en la entrega", "Error de facturación", "Atención en sucursal", "Otros"];
const URG = ['baja', 'media', 'alta'];
let categoria = null, urgencia = null, motivo = null;
try {
  const resp = JSON.parse($input.first().json.response || '{}');
  if (CATS.includes(resp.categoria)) categoria = resp.categoria; else motivo = 'Categoría no reconocida (la IA respondió: ' + (resp.categoria || 'nada') + ')';
  urgencia = URG.includes(resp.urgencia) ? resp.urgencia : 'media';
} catch (e) { motivo = 'Respuesta de la IA inválida'; }
return [{ json: { categoria, urgencia, motivo_ia: motivo } }];

const r = $('CA85a_Preparar').first().json;
const c = $('CA85a_Buscar_cliente').first().json;
const m = $('CA85a_Enmascarar').first().json;
const ia = $('CA85a_Validar_IA').first().json;
const cola = [];
if (r.sospechoso) cola.push({ origen: 'seguridad', motivo: r.motivo_seguridad + '. Se clasificó igual; no se ejecutó nada de lo que pide.', prioridad: 'alta' });
if (r.pedido_datos_personales) cola.push({ origen: 'reclamos', motivo: 'Pedido sobre datos personales (acceso, rectificación o supresión): derivar al Responsable de datos personales (Gerente de Administración). Tiene plazo legal.', prioridad: 'alta' });
if (!ia.categoria) cola.push({ origen: 'reclamos', motivo: ia.motivo_ia, prioridad: 'media' });
return [{ json: { reclamo_json: JSON.stringify({ reclamo_id: r.reclamo_id, cliente_id: c.cliente_id || null, sucursal: r.sucursal, canal: r.canal,
  fecha_hora_ingreso: r.fecha_hora_ingreso, texto_enmascarado: m.texto_enmascarado, categoria: ia.categoria, urgencia: ia.urgencia,
  es_pedido_datos_personales: r.pedido_datos_personales }), cola_json: JSON.stringify(cola) } }];

const r = $('CA85a_Preparar').first().json;
const c = $('CA85a_Buscar_cliente').first().json;
const m = $('CA85a_Enmascarar').first().json;
const ok = m.resuelto === true;
const ia = ok ? $('CA85a_Validar_IA').first().json : {};
const g = ok ? $('CA85a_Guardar').first().json : { registrado: false };
let estado;
if (!ok) estado = 'a_la_cola';
else if (!g.registrado) estado = 'Ya registrado antes';
else if (r.sospechoso) estado = 'sospechoso';
else if (r.pedido_datos_personales) estado = 'pedido_datos_personales';
else if (!ia.categoria) estado = 'a_la_cola';
else estado = 'clasificado';
return [{ json: { reclamo_id: r.reclamo_id, estado, cliente_id: c.cliente_id || null, cliente_identificado: c.resuelto === true,
  categoria: ia.categoria || null, urgencia: ia.urgencia || null, sospechoso: r.sospechoso, pedido_datos_personales: r.pedido_datos_personales,
  texto_enmascarado: m.texto_enmascarado || null, modelo_ia: ok ? 'qwen3.5:9b' : null, motivo: ok ? (r.motivo_seguridad || ia.motivo_ia || null) : m.motivo,
  sigue_a_derivacion: ['clasificado', 'sospechoso'].includes(estado) } }];

const r = $input.first().json;
return [{ json: { modo: 'fin', automatizacion_id: 'A08', documento_id: r.reclamo_id,
  estado: r.estado === 'sospechoso' ? 'bloqueado' : (['clasificado', 'Ya registrado antes'].includes(r.estado) ? 'ok' : 'derivado_a_cola'),
  intervencion_humana: false, modelo_ia: r.modelo_ia || '', auditar: r.sospechoso, actor: 'A08', accion: 'reclamo sospechoso', motivo: r.motivo || '' } }];
